/// <summary>
/// FTI print Contract
/// </summary>
[DataContract]
class METRebateFTIPrintContract
{
    container custInvoiceTableRecIds;

}

Method.Source:
/// <summary>
/// Get or sets customer invoice table recids in container
/// </summary>
/// <param name = "_custInvoiceTableRecIds">CustInvoiceTable recids</param>
/// <returns>container with custInvoiceTableRecId </returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public container parmCustInvoiceTableRecIds(container _custInvoiceTableRecIds = custInvoiceTableRecIds)
{
    custInvoiceTableRecIds = _custInvoiceTableRecIds;
    return custInvoiceTableRecIds;
}
